    for (let i = 0; i < 18; i++) c.add({ tipo:'vapor', x0:sorte(170, 560), y0:MAR - 2, x1:330 + sorte(-50, 50), y1:66 + sorte(-12, 12), dur:sorte(70, 110), f:sorte(0, 6), r:sorte(3, 6), x:0, y:0 });
