      postos++; toca('planta'); c.brilhos(NOTCH[v], CR + 4, 6, '#FFE27A');
      for (let k = 0; k < 4; k++) c.add({ tipo:'respingo', x:NOTCH[v] + sorte(-10, 10), y:CR + 1, t:k * 2, cor:'#8A6A4E' });
