        for (let k = 0; k < 16; k++) c.add({ tipo:'infiltra', x0:bx - 8 + sorte(-3, 3), y0:by + sorte(0, 4), x1:BACIA.x + sorte(-8, 8), y1:BACIA.y, dur:sorte(16, 34), f:sorte(0, 6) });
